<script setup>
import { ref, computed, watch } from 'vue'
const props = defineProps({ snapshot: Object, manual: Boolean, compact: Boolean })
const emit = defineEmits(['select-path','execute'])
const filter = ref('all'), kind = ref('all'), expanded = ref(null)
const dagTasks = ref({})
watch(() => props.snapshot, snapshot => {
  if (snapshot?.task_index === 0) dagTasks.value = {}
  const task = snapshot?.current_task
  if (task?.subtasks) dagTasks.value[task.dag_id] = { kind: task.kind, kind_name: task.kind_name, subtasks: task.subtasks }
}, { immediate: true })
const operators = ['CONTROL_PARSE', 'STREAM_FILTER_ROI', 'FFT_FIR', 'TENSOR_INFER', 'AGGREGATE_TRACK']
const names = ['图像识别','目标检测','视频分析','语音处理','信号计算']
const dagRows = computed(() => (props.snapshot?.dags || []).map(d => { const traces = (props.snapshot.recent_tasks || []).filter(r => r.dag_id === d.dag_id); return { ...d, traces, kind: traces[0]?.kind ?? dagTasks.value[d.dag_id]?.kind, kind_name: traces[0]?.kind_name ?? dagTasks.value[d.dag_id]?.kind_name } }).filter(d => (kind.value === 'all' || d.kind === kind.value) && (filter.value === 'all' || d.status === filter.value)))
const selectedDag = computed(() => dagRows.value.find(d => d.dag_id === expanded.value))
const details = computed(() => { const tasks = dagTasks.value[expanded.value]?.subtasks || []; const traces = selectedDag.value?.traces || []; return [...tasks.map(t => ({...t, ...traces.find(r => r.subtask_id === t.subtask_id)})), ...traces.filter(r => !tasks.some(t => t.subtask_id === r.subtask_id))] })
const rows = computed(() => (props.snapshot?.recent_tasks || []).filter(r => (kind.value === 'all' || r.kind === kind.value) && (filter.value === 'all' || (filter.value === 'done' ? r.accepted && r.completed : filter.value === 'late' ? r.accepted && !r.completed : !r.accepted))))
const fmt = v => v == null ? '—' : Number(v).toFixed(3)
const nodeName = n => props.snapshot.nodes.find(v=>v.id===n)?.kind==='cloud' ? 'C0' : 'E'+n
const path = r => r.path?.map(nodeName).join(' → ') || '—'
function selectCandidate(r) { emit('select-path', { ...r, source: props.snapshot.current_task.source, access_edge: props.snapshot.current_task.access_edge }) }
</script>
<template><div v-if="snapshot?.enable_dag_mode">
  <div class="control-row"><el-select v-model="kind" size="small" style="width:150px"><el-option label="全部业务" value="all"/><el-option v-for="(name,i) in names" :key="i" :label="name" :value="i"/></el-select><el-select v-model="filter" size="small" style="width:150px"><el-option label="全部状态" value="all"/><el-option label="等待" value="waiting"/><el-option label="执行中" value="active"/><el-option label="已完成" value="completed"/><el-option label="失败" value="failed"/></el-select></div>
  <el-table :data="dagRows" size="small" max-height="220" highlight-current-row @row-click="row => expanded = row.dag_id"><el-table-column prop="dag_id" label="DAG 任务"/><el-table-column prop="kind_name" label="业务类型"/><el-table-column prop="status" label="状态"/><el-table-column prop="finish_time_s" label="完成时间 (s)"/></el-table>
  <template v-if="selectedDag"><p>DAG {{ selectedDag.dag_id }} 子任务执行明细</p><el-table :data="details" size="small" max-height="280" highlight-current-row @row-click="row => emit('select-path', row)"><el-table-column prop="name" label="子任务"/><el-table-column label="算子" min-width="140"><template #default="{row}">{{ operators[row.op_type] }}</template></el-table-column><el-table-column prop="destination_label" label="目标节点"/><el-table-column prop="resource_name" label="芯片"/><el-table-column prop="comm_tier" label="通信级别"/><el-table-column label="重构 (s)"><template #default="{row}">{{ fmt(row.setup_delay_s) }}</template></el-table-column><el-table-column label="开始 (s)"><template #default="{row}">{{ fmt(row.start_time_s) }}</template></el-table-column><el-table-column label="结束 (s)"><template #default="{row}">{{ fmt(row.finish_time_s) }}</template></el-table-column><el-table-column prop="status" label="状态"/></el-table></template>
  <template v-if="!compact && snapshot.current_task"><p>当前子任务：{{ snapshot.current_task.name }}</p><el-table :data="snapshot.current_task.candidates.filter(c => c.valid)" max-height="220" size="small" @row-click="selectCandidate"><el-table-column prop="action_id" label="动作"/><el-table-column prop="destination_label" label="目标节点"/><el-table-column prop="resource_name" label="芯片"/><el-table-column v-if="manual" label="操作"><template #default="{row}"><el-button link type="primary" @click.stop="emit('execute',row.action_id)">执行</el-button></template></el-table-column></el-table></template>
</div><div v-else-if="compact" class="compact-task-table"><el-table :data="[...rows].reverse()" height="100%" size="small" highlight-current-row @row-click="row=>emit('select-path',row)" empty-text="尚未调度任务，请加载任务后开始推演"><el-table-column label="任务 ID" width="82"><template #default="{row}">T-{{ row.task_index }}</template></el-table-column><el-table-column prop="kind_name" label="任务类型" width="88"/><el-table-column label="源终端" width="70"><template #default="{row}">U{{ row.source }}</template></el-table-column><el-table-column label="执行节点" width="80"><template #default="{row}">{{ row.accepted?nodeName(row.destination):'—' }}</template></el-table-column><el-table-column prop="resource_name" label="计算资源" width="80"/><el-table-column label="传输路径" min-width="130"><template #default="{row}">{{ path(row) }}</template></el-table-column><el-table-column label="完成时延" width="88"><template #default="{row}">{{ row.accepted?fmt(row.delay)+' s':'—' }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><span :class="['task-state',row.accepted?(row.completed?'completed':'late'):'rejected']">{{ row.accepted?(row.completed?'按期完成':'超时'):'已拒绝' }}</span></template></el-table-column></el-table></div><div v-else><div class="panel-heading"><div><div class="eyebrow">TASK DISPATCH</div><h3>任务与候选动作</h3></div><span class="muted">选择动作或任务以高亮路径</span></div><template v-if="snapshot?.current_task"><div class="task-summary"><strong>#{{ snapshot.current_task.task_index }} · {{ snapshot.current_task.kind_name }}</strong><span>时隙 {{ snapshot.current_task.slot }}</span><span>U{{ snapshot.current_task.source }} → E{{ snapshot.current_task.access_edge }}</span><span>输入 / 输出 {{ fmt(snapshot.current_task.data_mb) }} / {{ fmt(snapshot.current_task.output_mb) }} MB</span><span>{{ fmt(snapshot.current_task.compute_gflop) }} GFLOP</span><span>时限 {{ fmt(snapshot.current_task.deadline_s) }} s</span><span>优先级 {{ snapshot.current_task.priority }}</span><span>{{ snapshot.current_task.feasible_action_count }} 个可行动作</span></div><el-table :data="snapshot.current_task.candidates" max-height="230" size="small" highlight-current-row @row-click="selectCandidate"><el-table-column prop="action_id" label="动作" width="65"/><el-table-column prop="destination_label" label="执行节点" width="105"/><el-table-column prop="resource_name" label="芯片" width="75"/><el-table-column label="多跳路径" min-width="150"><template #default="{row}">{{ path(row) }}</template></el-table-column><el-table-column label="算力 f"><template #default="{row}">{{ fmt(row.compute_share) }}</template></el-table-column><el-table-column label="功率 p"><template #default="{row}">{{ fmt(row.uplink_power) }}</template></el-table-column><el-table-column label="预估时延 / 能耗" min-width="130"><template #default="{row}">{{ fmt(row.estimated_delay) }} / {{ fmt(row.estimated_energy) }}</template></el-table-column><el-table-column v-if="manual" label="操作" width="85"><template #default="{row}"><el-button link type="primary" @click.stop="emit('execute',row.action_id)">执行</el-button></template></el-table-column></el-table></template><p v-else class="muted">当前没有待调度任务</p><div class="table-subhead"><h4>已调度任务流</h4><el-select v-model="kind" size="small" style="width:150px"><el-option label="全部业务" value="all"/><el-option v-for="(name,i) in names" :key="i" :label="name" :value="i"/></el-select><el-select v-model="filter" size="small" style="width:150px"><el-option label="全部状态" value="all"/><el-option label="按期完成" value="done"/><el-option label="超时未完成" value="late"/><el-option label="拒绝" value="rejected"/></el-select></div><el-table :data="rows" max-height="300" size="small" highlight-current-row @row-click="row => emit('select-path',row)"><el-table-column prop="task_index" label="任务" width="65"/><el-table-column prop="slot" label="时隙" width="60"/><el-table-column prop="kind_name" label="类型" width="100"/><el-table-column label="状态" width="100"><template #default="{row}"><span :class="row.accepted ? row.completed ? 'good' : 'warn' : 'bad'">{{ row.accepted ? row.completed ? '按期完成' : '超时' : '拒绝' }}</span></template></el-table-column><el-table-column label="路径" min-width="130"><template #default="{row}">{{ path(row) }}</template></el-table-column><el-table-column prop="resource_name" label="芯片" width="70"/><el-table-column label="f / p" min-width="110"><template #default="{row}">{{ fmt(row.compute_share) }} / {{ fmt(row.uplink_power) }}</template></el-table-column><el-table-column label="时延 / 能耗" min-width="115"><template #default="{row}">{{ fmt(row.delay) }} / {{ fmt(row.energy) }}</template></el-table-column><el-table-column label="奖励" width="80"><template #default="{row}">{{ fmt(row.reward) }}</template></el-table-column></el-table></div></template>
